import { useEffect, useMemo, type JSX, type ReactNode } from 'react';
import { AdminShell, HOST_SERVICE_IDS, type AdminShellProps } from '@cedros/admin-react';

import { SetupWizard } from '../components/admin/SetupWizard';
import { NonWalletLoginForm } from '../components/NonWalletLoginForm';
import { ErrorMessage } from '../components/shared/ErrorMessage';
import { useAuthState } from '../context/useCedrosLogin';
import { useOrgs } from '../hooks/useOrgs';
import { useSetup } from '../hooks/useSetup';
import { cedrosLoginPlugin } from './plugin';
import type { AdminPlugin, HostContext } from './types';

type CedrosLoginService = NonNullable<HostContext['cedrosLogin']>;
type OrgService = NonNullable<HostContext['org']>;

export interface CedrosUnifiedAdminProps extends Omit<AdminShellProps, 'plugins' | 'hostContext'> {
  additionalPlugins?: AdminPlugin[];
  hostContext?: HostContext;
  loginFallback?: ReactNode;
}

export function CedrosUnifiedAdmin({
  additionalPlugins = [],
  hostContext,
  loginFallback,
  loadingFallback,
  defaultSection = 'cedros-login:users',
  ...shellProps
}: CedrosUnifiedAdminProps): JSX.Element {
  const { config, user, authState, _internal } = useAuthState();
  const { activeOrg, role, permissions, isLoading: isOrgLoading, error: orgError } = useOrgs();
  const { status, isLoading, error, checkStatus } = useSetup();

  useEffect(() => {
    void checkStatus();
  }, [checkStatus]);

  const plugins = useMemo(
    () => buildPluginList(additionalPlugins),
    [additionalPlugins]
  );
  const mergedHostContext = useMemo(
    () => buildHostContext(hostContext, {
      serverUrl: config.serverUrl,
      user,
      getAccessToken: _internal?.getAccessToken ?? (() => null),
      activeOrg,
      role,
      permissions
    }),
    [hostContext, config.serverUrl, user, _internal, activeOrg, role, permissions]
  );

  if (error) {
    return <ErrorMessage error={`Failed to check admin setup status: ${error.message}`} autoFocus />;
  }

  if (orgError) {
    return <ErrorMessage error={`Failed to load admin organization context: ${orgError.message}`} autoFocus />;
  }

  if (isLoading || status === null || authState === 'loading' || (authState === 'authenticated' && isOrgLoading)) {
    return renderLoadingFallback(loadingFallback);
  }

  if (status.needsSetup) {
    return <SetupWizard onComplete={() => void checkStatus()} />;
  }

  if (authState !== 'authenticated' || !user) {
    return <>{loginFallback ?? <NonWalletLoginForm />}</>;
  }

  return (
    <AdminShell
      {...shellProps}
      loadingFallback={loadingFallback}
      defaultSection={defaultSection}
      plugins={plugins}
      hostContext={mergedHostContext}
    />
  );
}

function buildPluginList(additionalPlugins: AdminPlugin[]): AdminPlugin[] {
  const plugins = [cedrosLoginPlugin];

  for (const plugin of additionalPlugins) {
    if (plugin.id === cedrosLoginPlugin.id) {
      continue;
    }

    plugins.push(plugin);
  }

  return plugins;
}

function buildHostContext(
  hostContext: HostContext | undefined,
  loginState: {
    serverUrl: string;
    user: ReturnType<typeof useAuthState>['user'];
    getAccessToken: () => string | null;
    activeOrg: ReturnType<typeof useOrgs>['activeOrg'];
    role: ReturnType<typeof useOrgs>['role'];
    permissions: ReturnType<typeof useOrgs>['permissions'];
  }
): HostContext {
  const loginService: CedrosLoginService = {
    user: loginState.user
      ? {
          id: loginState.user.id,
          email: loginState.user.email,
          name: loginState.user.name,
          picture: loginState.user.picture
        }
      : null,
    getAccessToken: loginState.getAccessToken,
    serverUrl: loginState.serverUrl
  };
  const orgService = resolveOrgService(hostContext, loginState.activeOrg, loginState.role, loginState.permissions);

  return {
    ...hostContext,
    services: {
      ...hostContext?.services,
      [HOST_SERVICE_IDS.cedrosLogin]: loginService,
      ...(orgService ? { [HOST_SERVICE_IDS.org]: orgService } : {})
    },
    cedrosLogin: loginService,
    ...(orgService ? { org: orgService } : {})
  };
}

function resolveOrgService(
  hostContext: HostContext | undefined,
  activeOrg: ReturnType<typeof useOrgs>['activeOrg'],
  role: ReturnType<typeof useOrgs>['role'],
  permissions: ReturnType<typeof useOrgs>['permissions']
): OrgService | undefined {
  if (!activeOrg) {
    return hostContext?.org;
  }

  return {
    orgId: activeOrg.id,
    role: role ?? 'member',
    permissions: permissions ?? []
  };
}

function renderLoadingFallback(loadingFallback: ReactNode): JSX.Element {
  if (loadingFallback !== undefined) {
    return <>{loadingFallback}</>;
  }

  return <div>Loading admin...</div>;
}
