export const cedrosLoginPlugin: AdminPlugin = {
  id: 'cedros-login',
  name: 'Cedros Login',
  version: '1.0.0',

  sections: SECTIONS,

  groups: [
    { id: 'users', label: 'Users', order: 0 },
    { id: 'compliance', label: 'Compliance', order: 1 },
    { id: 'configuration', label: 'Configuration', order: 2 },
  ],

  components: {
    users: UsersSection,
    team: TeamSection,
    deposits: DepositsSection,
    withdrawals: WithdrawalsSection,
    referrals: ReferralsSection,
    'settings-auth': AuthenticationSettings,
    'settings-wallet': EmbeddedWalletSettings,
    'settings-email': EmailSettings,
    'settings-webhooks': WebhookSettings,
    'settings-credits': CreditSystemSettings,
    'settings-compliance': ComplianceSettingsSection,
    'settings-referrals': ReferralSettingsSection,
    'settings-signup': SignupSettingsSection,
    'settings-server': ServerSettings,
    'settings-images': ImageStorageSettingsSection,
    compliance: ComplianceSection,
    'accreditation-queue': AccreditationQueueSection,
    sanctions: SanctionsSection,
    'signup-gating': SignupGatingSection,
  },

  createPluginContext(hostContext: HostContext): PluginContext {
    const cedrosLogin = getHostService<CedrosLoginHostService>(
      hostContext,
      HOST_SERVICE_IDS.cedrosLogin
    );
    if (!cedrosLogin) {
      throw new Error(
        "cedros-login plugin requires the cedros-login host service"
      );
    }
    const org = getHostService<OrgHostService>(hostContext, HOST_SERVICE_IDS.org);

    return {
      serverUrl: cedrosLogin.serverUrl,
      userId: cedrosLogin.user?.id,
      getAccessToken: cedrosLogin.getAccessToken,
      hasPermission: (permission: string) => this.checkPermission(permission, hostContext),
      orgId: org?.orgId,
      pluginData: {
        user: cedrosLogin.user,
        orgRole: org?.role,
      },
    };
  },

  checkPermission(permission: string, hostContext: HostContext): boolean {
    const org = getHostService<OrgHostService>(hostContext, HOST_SERVICE_IDS.org);
    const login = getHostService<CedrosLoginHostService>(hostContext, HOST_SERVICE_IDS.cedrosLogin);

    // No org context = admin-level access (for global admins)
    if (!org) {
      // Check if user is in cedrosLogin context - assume admin if present
      return Boolean(login?.user);
    }

    const requiredPerms = PERMISSION_MAP[permission as LoginPermission];
    if (!requiredPerms) {
      // Unknown permission - default deny
      return false;
    }

    // Check if user has any of the required permissions
    return requiredPerms.some(
      (p) =>
        org.permissions.includes(p) ||
        p === org.role ||
        (p === 'admin' && ['admin', 'owner'].includes(org.role)) ||
        (p === 'owner' && org.role === 'owner')
    );
  },

  cssNamespace: 'cedros-dashboard',
};

